            Text(
                text = stringResource(R.string.player_actions_hint),
                style = MaterialTheme.typography.bodySmall,
                color = Color.White.copy(alpha = 0.62f),
                modifier = Modifier.padding(horizontal = 10.dp),
            )
            actions.chunked(columns).forEachIndexed { rowIndex, rowActions ->
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(6.dp),
                ) {
                    rowActions.forEachIndexed { colIndex, action ->
                        val index = rowIndex * columns + colIndex
                        val isDragging = draggingIndex == index
                        val shift = cellTranslations[action]?.value ?: Offset.Zero
                        Column(
                            horizontalAlignment = Alignment.CenterHorizontally,
                            modifier = Modifier
                                .weight(1f)
                                .clip(RoundedCornerShape(14.dp))
                                .background(
                                    if (isDragging) {
                                        MaterialTheme.colorScheme.primary.copy(alpha = 0.22f)
                                    } else {
                                        Color.Transparent
                                    },
                                )
                                .graphicsLayer {
                                    if (isDragging) {
                                        translationX = dragOffset.x
                                        translationY = dragOffset.y
                                        scaleX = 1.1f
                                        scaleY = 1.1f
                                    } else {
                                        translationX = shift.x
                                        translationY = shift.y
                                    }
                                }
                                .onGloballyPositioned { cellRects[index] = it.boundsInRoot() }
                                .pointerInput(Unit) {
                                    detectDragGesturesAfterLongPress(
                                        onDragStart = {
                                            draggingIndex = index
                                            dragOffset = Offset.Zero
                                        },
                                        onDragEnd = {
                                            draggingIndex = -1
                                            dragOffset = Offset.Zero
                                        },
                                        onDragCancel = {
                                            draggingIndex = -1
                                            dragOffset = Offset.Zero
                                        },
                                        onDrag = { change, amount ->
                                            change.consume()
                                            if (draggingIndex < 0) {
                                                return@detectDragGesturesAfterLongPress
                                            }
                                            dragOffset += amount
                                            val from = draggingIndex
                                            val fromRect = cellRects[from]
                                                ?: return@detectDragGesturesAfterLongPress
                                            val draggedCenter = fromRect.center + dragOffset
                                            val target = cellRects.entries
                                                .firstOrNull { (key, rect) ->
                                                    key != from &&
                                                        rect.inflate(gapPx)
                                                            .contains(draggedCenter)
                                                }?.key
                                            if (target != null) {
                                                reorder(from, target)
                                                // 交换后保持拖拽项跟随手指
                                                dragOffset += fromRect.center -
                                                    (cellRects[target] ?: fromRect).center
                                                draggingIndex = target
                                            }
                                        },
                                    )
                                }
                                .clickable { onActionClick(action) }
                                .padding(vertical = 12.dp),
                        ) {
                            Icon(
                                imageVector = action.icon(),
                                contentDescription = null,
                                tint = Color.White,
                                modifier = Modifier.size(26.dp),
                            )
                            Spacer(modifier = Modifier.height(6.dp))
                            Text(
                                text = stringResource(action.labelRes()),
                                style = MaterialTheme.typography.labelSmall,
                                color = Color.White,
                                maxLines = 1,
                            )
                        }
                    }
                    repeat(columns - rowActions.size) {
                        Spacer(modifier = Modifier.weight(1f))
                    }
                }
            }
        }
    }
}
